('basic',	0,	3,	3,	'en',	0,	'<script type=\"text/javascript\">\r\nvar gaJsHost = ((\"https:\" == document.location.protocol) ? \"https://ssl.\" : \"http://www.\");\r\ndocument.write(unescape(\"%3Cscript src=\'\" + gaJsHost + \"google-analytics.com/ga.js\' type=\'text/javascript\'%3E%3C/script%3E\"));\r\n</script><script type=\"text/javascript\">\r\ntry {\r\nvar pageTracker = _gat._getTracker(\"UA-4857461-8\");\r\npageTracker._trackPageview();\r\n} catch(err) {}\r\n</script><style>\r\nh6{\r\nmargin-top:-10px;\r\ntext-align: center;\r\ncolor:white;\r\n}\r\n.inner_footer{\r\nheight: 90px;\r\nwidth:1090px;\r\n}\r\n</style><p class=\"test-footer\" style=\"color:#FFFFFF;font-size:12px;line-height:30px;margin-top:0px 0px 0px 0px;padding:5px 0px 0px;text-align:center;\">Disclaimer: OPENFOAM® is a registered trade mark of OpenCFD Limited, producer and distributor of the OpenFOAM software. This work is licensed under a <a style=\"color:#FFFFFF;\" href=\"http://creativecommons.org/licenses/by-sa/4.0/\" rel=\"license\">Creative Commons Attribution-ShareAlike 4.0 International License</a> <a href=\"http://creativecommons.org/licenses/by-sa/4.0/\" rel=\"license\"><img style=\"border-width:0;\" src=\"https://i.creativecommons.org/l/by-sa/4.0/88x31.png\" alt=\"Creative Commons License\" width=\"88\" height=\"31\"></a></p>',	'',	'full_html'),
('basic',	0,	4,	4,	'en',	0,	'<!--<div id=\"block-menu-menu-fossee\">-->\r\n<span align=\"left\"><h4 ><a href=\"http://fossee.in/\" target =\"_blank\">FOSSEE</a></h4></span>\r\n\r\n<ul class=\"menu\">\r\n  <li class=\"leaf first\">\r\n    <a href=\"scilab\" title=\"Scilab\">Scilab</a>\r\n  </li>\r\n  <li class=\"leaf\">\r\n    <a href=\"freeeda\" title=\"FreeEDA\">FreeEDA</a>\r\n  </li>\r\n  <li class=\"leaf last\">\r\n    <a href=\"python\" title=\"Python\">Python</a>\r\n  </li>\r\n<li class=\"leaf\"><a title=\"Osdag\" href=\"/Osdag\">Osdag</a></li>\r\n   <li class=\"leaf last\">\r\n    <a href=\"or-tools\" title=\"OR-Tools\">OR-Tools</a>\r\n  </li>\r\n</ul>\r\n\r\n<!--</div>-->\r\n\r\n<!--<style type=\"text/css\">\r\n.fossee-logo a{\r\n    color:#000000;\r\n    text-decoration:none;\r\n    font-size:0.5em;\r\n    -webkit-transition: all .5s ease-out;\r\n    -moz-transition: all .5s ease-out;\r\n    -o-transition: all .5s ease-out;\r\n    transition: all .5s ease-out;\r\n  }\r\n  .fossee-logo a:hover{\r\n    color: #FFCB05;\r\n  }</style>-->',	NULL,	'full_html'),
