INSERT INTO `lecture_videos` (`id`, `video_sno`, `video_title`, `video_description_text`, `video_description_text_format`, `script_file_link`, `video_link`, `video_visibility`, `creation_date`) VALUES
(1,	1,	'Introduction',	'<p>This lecture is dedicated towards introduction and a brief overview of the subject.</p>\r\n',	'full_html',	'https://static.fossee.in/cfd/videos/lecture_videos/Lec_1/Lec1_script.pdf',	'https://static.fossee.in/cfd/videos/lecture_videos/Lec_1/Sumant_Lec1_OpenFoam_V2.mp4',	'N',	1669008778),
(2,	2,	'Overview of the CFD methodology',	'<p>Discussion about the various steps involved in CFD study.&nbsp;</p>\r\n',	'full_html',	'https://static.fossee.in/cfd/videos/lecture_videos/Lec_2/Script_OpenFOAM_Lecture_2.pdf',	'https://static.fossee.in/cfd/videos/lecture_videos/Lec_2/Sumant_Lec2_OpenFoam_V2.mp4',	'N',	1669009129),
(3,	3,	'Essential governing laws and their implementations by OpenFOAM in CFD & HT ',	'<p>Discussion on the governing laws for study of CFD &amp; Heat Transfer, plus energy conservation laws and terminology which is involved in formation of the energy conservation laws.&nbsp;</p>\r\n',	'full_html',	'https://static.fossee.in/cfd/videos/lecture_videos/Lec_3/Script_OpenFOAM_Lec3_Sumant.pdf',	'https://static.fossee.in/cfd/videos/lecture_videos/Lec_3/Sumant_Lec3_OpenFoam_V2.mp4',	'N',	1669010491),
(4,	4,	'Essential governing laws and & OpenFOAM implementation',	'<p>This tutorial is the part II of the 3rd video lecture and is mainly based on computational heat convection.</p>\r\n',	'full_html',	'https://static.fossee.in/cfd/videos/lecture_videos/Lec_4/Lec4_scrippt.pdf',	'https://static.fossee.in/cfd/videos/lecture_videos/Lec_4/Sumant_Lec4_OpenFoam_V2.mp4',	'N',	1669022227),
(5,	5,	'Physical flow governing laws',	'<p>This tutorial is based on essential flow governing laws and their OpenFOAM implementations.</p>\r\n',	'full_html',	'https://static.fossee.in/cfd/videos/lecture_videos/Lec_5/Sumant_Lec5_OpenFOAM.pdf',	'https://static.fossee.in/cfd/videos/lecture_videos/Lec_5/Sumant_Lec5_OpenFoam.mp4',	'N',	1669022422),
(6,	6,	'Discretisation of flow governing laws ',	'<p>This tutorial is based on discretisation of flow governing laws and their OpenFOAM implementations.&nbsp;</p>\r\n',	'full_html',	'https://static.fossee.in/cfd/videos/lecture_videos/Lec_6/Sumant_OpenFOAM_Lec6.pdf',	'https://static.fossee.in/cfd/videos/lecture_videos/Lec_6/Sumant_OpenFOAM_Lec_6.mp4',	'N',	1669022589),
(7,	7,	'Essential flow governing laws & OpenFOAM implementation',	'<p>Essential flow governing laws &amp; OpenFOAM implementation and illustrative examples.</p>\r\n',	'full_html',	'https://static.fossee.in/cfd/videos/lecture_videos/Lec_7/Sumant_OpenFOAM_Lec7.pdf',	'https://static.fossee.in/cfd/videos/lecture_videos/Lec_7/Sumant_OpenFOAM_Lec7_V2.mp4',	'N',	1669193849),
(8,	8,	'Solution to complex geometry problems in OpenFOAM',	'<p>Solution to complex geometry problems in OpenFOAM</p>\r\n',	'full_html',	'https://static.fossee.in/cfd/videos/lecture_videos/Lec_8/Sumant_OpenFOAM_Lec8.pdf',	'https://static.fossee.in/cfd/videos/lecture_videos/Lec_8/Sumant_OpenFOAM_Lec8_V2.mp4',	'N',	1669194019);
