('list_of_faculty_partners',	0,	288,	288,	'und',	0,	'<p style=\"border: 0px; font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px; margin: 0px 0px 0.5em; outline: 0px; padding: 0px; vertical-align: baseline; line-height: 2em; color: rgb(85, 85, 85); background-color: rgb(252, 252, 252);\"><span style=\"font-size:12px;\"><strong><span style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\"><span style=\"border: 0px; font-family: arial, helvetica, sans-serif; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Designation:&nbsp;</span></span></strong></span></p>\r\n\r\n<p style=\"border: 0px; font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px; margin: 0px 0px 0.5em; outline: 0px; padding: 0px; vertical-align: baseline; line-height: 2em; color: rgb(85, 85, 85); background-color: rgb(252, 252, 252);\"><span style=\"font-size:12px;\"><span style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\"><span style=\"border: 0px; font-family: arial, helvetica, sans-serif; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Assistant Professor,&nbsp;Mechanical Engineering Dept.&nbsp;</span></span></span></p>\r\n\r\n<p style=\"border: 0px; font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 14px; margin: 0px 0px 0.5em; outline: 0px; padding: 0px; vertical-align: baseline; line-height: 2em; color: rgb(85, 85, 85); background-color: rgb(252, 252, 252);\"><span style=\"font-size:12px;\"><strong><span style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\"><span style=\"border: 