DROP TABLE IF EXISTS `webform_submission_data`;
CREATE TABLE `webform_submission_data` (
  `webform_id` varchar(32) NOT NULL COMMENT 'The webform id.',
  `sid` int NOT NULL COMMENT 'The unique identifier for this submission.',
